(()=>{'use strict';function initMultiStep(form){const steps=Array.from(form.querySelectorAll('.nexley-forms__step'));if(steps.length <=1)return;let currentStep=0;let progressBar=form.querySelector('.nexley-forms__progress');if(!progressBar){progressBar=document.createElement('div');progressBar.className='nexley-forms__progress';progressBar.setAttribute('role','progressbar');progressBar.setAttribute('aria-valuemin','1');progressBar.setAttribute('aria-valuemax',String(steps.length));form.insertBefore(progressBar,form.firstChild);steps.forEach((_,idx)=>{const seg=document.createElement('div');seg.className='nexley-forms__progress-step'+(idx===0?' is-active':'');progressBar.appendChild(seg);});}const submitBtn=form.querySelector('.nexley-forms__submit');const navBar=document.createElement('div');navBar.className='nexley-forms__step-nav';const prevBtn=document.createElement('button');prevBtn.type='button';prevBtn.className='nexley-forms__submit nexley-forms__submit--prev';prevBtn.textContent='Previous';prevBtn.style.display='none';const nextBtn=document.createElement('button');nextBtn.type='button';nextBtn.className='nexley-forms__submit nexley-forms__submit--next';nextBtn.textContent='Next';navBar.appendChild(prevBtn);navBar.appendChild(nextBtn);const statusEl=form.querySelector('.nexley-forms__status');if(statusEl){form.insertBefore(navBar,statusEl);}else{form.appendChild(navBar);}if(submitBtn){submitBtn.style.display='none';}function updateStep(){steps.forEach((step,idx)=>{const isCurrent=idx===currentStep;step.hidden=!isCurrent;if(isCurrent)step.removeAttribute('aria-hidden');else step.setAttribute('aria-hidden','true');});const progressSteps=form.querySelectorAll('.nexley-forms__progress-step');progressSteps.forEach((seg,idx)=>{if(idx <=currentStep)seg.classList.add('is-active');else seg.classList.remove('is-active');});if(progressBar){progressBar.setAttribute('aria-valuenow',String(currentStep+1));}prevBtn.style.display=currentStep>0?'inline-flex':'none';if(currentStep===steps.length-1){nextBtn.style.display='none';if(submitBtn)submitBtn.style.display='inline-flex';}else{nextBtn.style.display='inline-flex';if(submitBtn)submitBtn.style.display='none';}}nextBtn.addEventListener('click',(e)=>{e.preventDefault();const currentStepEl=steps[currentStep];const inputs=currentStepEl.querySelectorAll('input:not([disabled]),select:not([disabled]),textarea:not([disabled])');for(const input of inputs){if(input.checkValidity && !input.checkValidity()){if(input.reportValidity)input.reportValidity();return;}}if(currentStep < steps.length-1){currentStep++;updateStep();}});prevBtn.addEventListener('click',(e)=>{e.preventDefault();if(currentStep>0){currentStep--;updateStep();}});updateStep();}function initAll(){document.querySelectorAll('.nexley-forms').forEach((form)=>{if(form.querySelectorAll('.nexley-forms__step').length>1){initMultiStep(form);}});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initAll);}else{initAll();}})();